declare(strict_types=1);
$pageTitle='Route Stops';$pageKey='transport_management';require dirname(__DIR__).'/includes/layout-start.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();if(empty($_SESSION['route_stops_csrf_token'])||!is_string($_SESSION['route_stops_csrf_token']))$_SESSION['route_stops_csrf_token']=bin2hex(random_bytes(32));$stopsCsrf=$_SESSION['route_stops_csrf_token'];$routeId=(int)($_GET['route_id']??0);
