<style>
.stop-page{display:grid;gap:16px}.stop-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px}.stop-head h1{margin:0;font-size:clamp(24px,2vw,30px)}.stop-actions{display:flex;gap:9px;flex-wrap:wrap}.stop-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.stop-stat{border-radius:14px;padding:18px;color:#fff;min-height:105px;display:flex;align-items:center;gap:13px}.stop-stat.purple{background:linear-gradient(135deg,#7448e8,#4b36cf)}.stop-stat.green{background:linear-gradient(135deg,#45c783,#1ea568)}.stop-stat.orange{background:linear-gradient(135deg,#ffb327,#ff8a17)}.stop-stat span{width:46px;height:46px;border-radius:50%;background:rgba(255,255,255,.16);display:grid;place-items:center}.stop-stat span svg{width:23px}.stop-stat small{display:block;font-weight:700;font-size:11px}.stop-stat strong{display:block;font-size:25px;margin-top:4px}.stop-card{border-radius:14px;overflow:hidden}.stop-filter{padding:14px 16px;display:grid;grid-template-columns:minmax(260px,1fr) auto;gap:10px;border-bottom:1px solid var(--border-soft,#e7ebf3)}.stop-table-wrap{overflow-x:auto}.stop-table{width:100%;min-width:760px}.stop-table th,.stop-table td{padding:11px 10px}.stop-table th{font-size:10px;white-space:nowrap}.stop-table td{font-size:11px}.stop-badge{display:inline-flex;padding:5px 9px;border-radius:999px;font-size:9px;font-weight:800}.stop-badge.active{color:#16834f;background:#e8f8ef}.stop-badge.inactive{color:#dc2626;background:#fff0f1}.stop-actions-cell{display:flex;gap:5px}.stop-action{width:31px;height:31px;border:1px solid #d7def1;border-radius:7px;background:var(--card-bg,#fff);display:grid;place-items:center;color:#2563eb}.stop-action.delete{color:#dc2626}.stop-action svg{width:14px}.stop-empty{text-align:center!important;padding:38px!important}.stop-toast{position:fixed;right:18px;top:18px;z-index:2200;width:min(390px,calc(100vw - 36px));padding:13px 15px;border-radius:10px;color:#fff;opacity:0;visibility:hidden;transform:translateY(-8px);transition:.2s;box-shadow:0 18px 40px rgba(15,23,42,.18);font-size:12px;font-weight:700}.stop-toast.show{opacity:1;visibility:visible;transform:translateY(0)}.stop-toast.success{background:#16834f}.stop-toast.error{background:#dc2626}.stop-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}@media(max-width:767px){.stop-head{flex-direction:column}.stop-actions{display:grid;grid-template-columns:1fr 1fr;width:100%}.stop-stats{grid-template-columns:1fr}.stop-filter,.stop-form-grid{grid-template-columns:1fr}}
</style>
<div id="stopToast" class="stop-toast"></div><div class="stop-page"><div class="stop-head"><div><h1 id="routeHeading">Route Stops</h1><p id="routeSummary" class="text-muted">Loading route...</p></div><div class="stop-actions"><a href="transport-routes.php" class="btn-ui"><i data-lucide="arrow-left"></i> Route Master</a><button id="addStopBtn" class="btn-ui btn-primary-ui" type="button"><i data-lucide="plus"></i> Add Stop</button></div></div><section class="stop-stats"><article class="stop-stat purple"><span><i data-lucide="map-pin"></i></span><div><small>Total Stops</small><strong id="statTotalStops">0</strong></div></article><article class="stop-stat green"><span><i data-lucide="circle-check-big"></i></span><div><small>Active Stops</small><strong id="statActiveStops">0</strong></div></article><article class="stop-stat orange"><span><i data-lucide="circle-pause"></i></span><div><small>Inactive Stops</small><strong id="statInactiveStops">0</strong></div></article></section><section class="ui-card stop-card"><div class="stop-filter"><input id="stopSearch" class="form-control" type="search" placeholder="Search Stop Name"><button id="resetStopSearch" class="btn-ui"><i data-lucide="rotate-ccw"></i> Reset</button></div><div class="stop-table-wrap"><table class="data-table stop-table"><thead><tr><th>Order</th><th>Stop Name</th><th>Transport Fee</th><th>Status</th><th>Actions</th></tr></thead><tbody id="stopTableBody"><tr><td colspan="5" class="stop-empty">Loading stops...</td></tr></tbody></table></div></section></div>
<div class="modal fade" id="stopModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="stopForm"><div class="modal-header"><h5 id="stopModalTitle" class="modal-title">Add Stop</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body stop-form-grid"><input id="stopId" type="hidden"><div><label class="form-label">Stop Name *</label><input id="stopName" class="form-control" maxlength="150" required></div><div><label class="form-label">Stop Order *</label><input id="stopOrder" class="form-control" type="number" min="1" max="999" required></div><div><label class="form-label">Transport Fee *</label><input id="transportFee" class="form-control" type="number" min="0" max="99999999.99" step="0.01" value="0.00" placeholder="Example: 1500.00" required></div><div><label class="form-label">Status *</label><select id="stopStatus" class="form-select"><option value="active">Active</option><option value="inactive">Inactive</option></select></div></div><div class="modal-footer"><button id="resetStopForm" type="button" class="btn-ui">Reset</button><button type="button" class="btn-ui" data-bs-dismiss="modal">Cancel</button><button id="saveStopBtn" type="submit" class="btn-ui btn-primary-ui"><i data-lucide="save"></i><span id="saveStopText">Add Stop</span></button></div></form></div></div></div>
<div class="modal fade" id="deleteStopModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Delete Stop</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p>Delete this route stop?</p><div class="alert alert-warning"><strong id="deleteStopLabel">-</strong></div></div><div class="modal-footer"><button type="button" class="btn-ui" data-bs-dismiss="modal">Cancel</button><button id="confirmDeleteStop" type="button" class="btn-ui btn-primary-ui">Delete Stop</button></div></div></div></div>
<script>
(function(){'use strict';const routeId=<?=json_encode($routeId)?>,apiUrl=new URL('../api/route-stops.php',location.href).href;let csrf=<?=json_encode($stopsCsrf)?>,records=[],deleteId=0,timer=null,toastTimer=null;const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])),money=v=>'₹'+Number(v||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});function toast(m,s){const e=$('stopToast');e.className='stop-toast show '+(s?'success':'error');e.textContent=m;clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.className='stop-toast',5000)}async function request(action,data={},method='GET'){let res;if(method==='GET'){const u=new URL(apiUrl);u.searchParams.set('action',action);u.searchParams.set('route_id',routeId);Object.keys(data).forEach(k=>{if(data[k]!==''&&data[k]!==null)u.searchParams.set(k,data[k])});res=await fetch(u,{credentials:'same-origin',headers:{Accept:'application/json'}})}else res=await fetch(apiUrl,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify(Object.assign({action,route_id:routeId,csrf_token:csrf},data))});const t=await res.text();let r;try{r=JSON.parse(t)}catch(e){throw new Error('Route Stops API returned HTTP '+res.status+'. '+t.slice(0,180))}if(!res.ok||!r.success)throw new Error(r.message||'Request failed.');if(r.data?.csrf_token)csrf=r.data.csrf_token;return r}function render(rows){records=rows||[];$('stopTableBody').innerHTML=records.map(r=>'<tr><td><strong>'+Number(r.stop_order)+'</strong></td><td>'+esc(r.stop_name)+'</td><td><strong>'+money(r.transport_fee)+'</strong></td><td><span class="stop-badge '+esc(r.status)+'">'+esc(r.status)+'</span></td><td><div class="stop-actions-cell"><button class="stop-action js-edit" data-id="'+Number(r.id)+'"><i data-lucide="pencil"></i></button><button class="stop-action delete js-delete" data-id="'+Number(r.id)+'"><i data-lucide="trash-2"></i></button></div></td></tr>').join('')||'<tr><td colspan="5" class="stop-empty">No route stops found.</td></tr>';document.querySelectorAll('.js-edit').forEach(b=>b.onclick=()=>openForm(Number(b.dataset.id)));document.querySelectorAll('.js-delete').forEach(b=>b.onclick=()=>openDelete(Number(b.dataset.id)));if(window.lucide)lucide.createIcons()}async function load(){if(routeId<=0){$('routeHeading').textContent='Invalid Route';$('routeSummary').textContent='Open this page from Route Master.';$('addStopBtn').disabled=true;$('stopTableBody').innerHTML='<tr><td colspan="5" class="stop-empty">Invalid route ID.</td></tr>';toast('Invalid route ID.',false);return}try{const r=await request('list',{search:$('stopSearch').value.trim()});const route=r.data.route;$('routeHeading').textContent=route.route_name+' Stops';const routeParts=[route.route_code||'',route.zone_area||'',route.start_point&&route.end_point?route.start_point+' → '+route.end_point:(route.start_point||route.end_point||'')].filter(Boolean);$('routeSummary').textContent=routeParts.join(' • ')||'Route details';const s=r.data.stats||{};$('statTotalStops').textContent=Number(s.total_stops||0);$('statActiveStops').textContent=Number(s.active_stops||0);$('statInactiveStops').textContent=Number(s.inactive_stops||0);render(r.data.records||[])}catch(e){$('stopTableBody').innerHTML='<tr><td colspan="5" class="stop-empty">'+esc(e.message)+'</td></tr>';toast(e.message,false)}}function clearForm(){$('stopForm').reset();$('stopId').value='';$('stopStatus').value='active';$('stopOrder').value=records.length+1;$('transportFee').value='0.00';$('stopModalTitle').textContent='Add Stop';$('saveStopText').textContent='Add Stop'}function openForm(id=0){clearForm();if(id){const r=records.find(x=>Number(x.id)===id);if(!r)return;$('stopId').value=r.id;$('stopName').value=r.stop_name;$('stopOrder').value=r.stop_order;$('transportFee').value=Number(r.transport_fee||0).toFixed(2);$('stopStatus').value=r.status;$('stopModalTitle').textContent='Update Stop';$('saveStopText').textContent='Update Stop'}bootstrap.Modal.getOrCreateInstance($('stopModal')).show();setTimeout(()=>$('stopName').focus(),200)}async function save(e){e.preventDefault();const data={id:Number($('stopId').value||0),stop_name:$('stopName').value.trim(),stop_order:Number($('stopOrder').value||0),transport_fee:Number($('transportFee').value||0),status:$('stopStatus').value};if(!data.stop_name){toast('Stop Name is required.',false);return}if(data.stop_order<1){toast('Stop Order is required.',false);return}if(!Number.isFinite(data.transport_fee)||data.transport_fee<0){toast('Enter a valid Transport Fee.',false);return}const b=$('saveStopBtn');b.disabled=true;try{const r=await request('save',data,'POST');bootstrap.Modal.getInstance($('stopModal'))?.hide();toast(r.message,true);await load()}catch(e){toast(e.message,false)}finally{b.disabled=false}}function openDelete(id){deleteId=id;const r=records.find(x=>Number(x.id)===id);$('deleteStopLabel').textContent=r?r.stop_order+' • '+r.stop_name:'Selected stop';bootstrap.Modal.getOrCreateInstance($('deleteStopModal')).show()}async function remove(){if(!deleteId)return;try{const r=await request('delete',{id:deleteId},'POST');bootstrap.Modal.getInstance($('deleteStopModal'))?.hide();toast(r.message,true);deleteId=0;await load()}catch(e){toast(e.message,false)}}$('addStopBtn').onclick=()=>openForm();$('stopForm').onsubmit=save;$('resetStopForm').onclick=()=>{const id=Number($('stopId').value||0);openForm(id)};$('confirmDeleteStop').onclick=remove;$('stopSearch').oninput=()=>{clearTimeout(timer);timer=setTimeout(load,300)};$('resetStopSearch').onclick=()=>{$('stopSearch').value='';load()};load();if(window.lucide)lucide.createIcons()})();
</script>
